style.css:
@-moz-document url-prefix("https://awscertificationpractice.benchprep.com") {
.toolbar{background: var(--gray-00);}

:root {--gray: #D2D2D2;
    --gray-100: #FFFFFF;
    --gray-90: #F6F6F6;
    --gray-80: #EDEDED;
    --gray-70: #E4E4E4;
    --gray-60: #DBDBDB;
    --gray-50: #D2D2D2;
    --gray-40: #9E9E9E;
    --gray-30: #828282;
    --gray-20: #696969;
    --gray-10: #353535;
    --gray-00: #000000;
    --primary: #5e8cbd;
    --primary-50: #2f4366;
    --content-dark: #FFFFFF;
    --content-medium: #EDEDED;
    --red-90: #f8d6d7;
    --red-80: #f1adae;
    --red-70: #ea8486;
    --red-60: #e35b5d;
    --red-50: #dc3235;
    --red-40: #bf2c2e;
    --red-30: #a52628;
    --red-20: #881f21;
    --red-10: #6e191b;
    --green-90: #cce6dd;
    --green-80: #99cdba;
    --green-70: #66b398;
    --green-60: #339a75;
    --green-50: #008153;
    --green-40: #007048;
    --green-30: #00613e;
    --green-20: #005033;
    --green-10: #00412a;
    --border: #828282;}

div.pagination li.active span {background: var(--gray-30);}

div.li-cell.answer-preview.preview.content-container {color: var(--gray-90);}

#question-app {background: var(--gray-10) !important;}

ul.list-table li.header {color: var(--gray-70);}
}
